import{_ as d,o as r,c as e,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const g=JSON.parse('{"title":"术语表","description":"","frontmatter":{},"headers":[],"relativePath":"webgl-graphics-course/glossary.md","filePath":"webgl-graphics-course/docs/glossary.md"}'),o={name:"webgl-graphics-course/glossary.md"};function i(n,t,s,l,c,p){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>全书按首教顺序出现的术语与概念，一句大白话定义——忘了哪个词，回这里查。</p><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话定义</th></tr></thead><tbody><tr><td>顶点</td><td>vertex</td><td>构成形状的角点，GPU 一切绘制的原料单位。</td></tr><tr><td>片元</td><td>fragment</td><td>候选像素：光栅化切出来的每个小格子，涂上颜色后才成为屏幕像素。</td></tr><tr><td>着色器</td><td>shader</td><td>写给 GPU 的小函数，决定每个顶点落在哪、每个格子涂什么色。</td></tr><tr><td>GLSL</td><td>OpenGL Shading Language</td><td>写着色器用的小语言：C 的风味、类型严格，源码在运行时编译到 GPU。</td></tr><tr><td>顶点着色器</td><td>vertex shader</td><td>管线第一段的可编程岗位：对每个顶点算位置，结果写入 gl_Position。</td></tr><tr><td>片元着色器</td><td>fragment shader</td><td>管线第三段的可编程岗位：对每个片元算颜色，结果写入 gl_FragColor。</td></tr><tr><td>光栅化</td><td>rasterization</td><td>把顶点连成的形状翻译成『哪些格子要涂色』的过程。</td></tr><tr><td>缓冲区</td><td>buffer</td><td>一次性运进显存的二进制数据块，装顶点坐标等原料。</td></tr><tr><td>顶点属性</td><td>attribute</td><td>顶点着色器的逐顶点输入，如每个顶点的坐标、颜色。</td></tr><tr><td>统一变量</td><td>uniform</td><td>整次绘制里全场统一的只读输入，如当前旋转角度、光源位置。</td></tr><tr><td>可变变量</td><td>varying</td><td>顶点着色器传给片元着色器的值，沿线自动渐变（插值）。</td></tr><tr><td>裁剪坐标系</td><td>clip coordinates</td><td>顶点着色器写进 gl_Position 的半成品坐标（还没除以 w）；GPU 在此按 x、y、z 不超过 w 裁掉视野外的点。w=1 时与 NDC 重合。</td></tr><tr><td>NDC</td><td>normalized device coordinates</td><td>GPU 的标准操场：透视除法之后 x/y/z 都在 [-1,1]，任何坐标先换算成它才有效。</td></tr><tr><td>视口</td><td>viewport</td><td>NDC 操场映射到屏幕上的那块矩形区域。</td></tr><tr><td>渲染循环</td><td>render loop</td><td>每帧清屏→更新→重画的循环，动画的心跳。</td></tr><tr><td>增量时间</td><td>delta time</td><td>与上一帧的时间差，用它缩放动画量，帧率不匀也等速。</td></tr><tr><td>线性插值</td><td>linear interpolation, lerp</td><td>按比例 t 取 A 到 B 之间的值，动画与渐变的基本砖。</td></tr><tr><td>缓动</td><td>easing</td><td>先把比例 t 整形（如 smoothstep 的 S 曲线）再插值的手法，消除匀速动画的机械感。</td></tr><tr><td>精度限定符</td><td>precision qualifier</td><td>声明浮点数按哪一档精度算的前缀：lowp/mediump/highp 三档；片元着色器必须显式声明 float 精度。</td></tr><tr><td>向量</td><td>vector</td><td>带方向的走法说明：朝哪走、走多远。</td></tr><tr><td>点积</td><td>dot product</td><td>两向量方向的一致度：同向为正、垂直为零、反向为负。</td></tr><tr><td>叉积</td><td>cross product</td><td>两向量撑出的垂直方向，右手定则定指向。</td></tr><tr><td>归一化</td><td>normalization</td><td>把向量长度缩成 1，只留方向。</td></tr><tr><td>单位向量</td><td>unit vector</td><td>长度为 1 的向量，只留方向的标准形态；「只要方向」的场合一律先归一化成它。</td></tr><tr><td>向量投影</td><td>projection</td><td>一个向量沿另一方向压平后剩下的长度；用单位向量当尺子点积，读数即投影。</td></tr><tr><td>矩阵</td><td>matrix</td><td>装满数字的变换机器：坐标进去、变换后的坐标出来。</td></tr><tr><td>列主序</td><td>column-major</td><td>数组按列连续存放矩阵元素，WebGL 读数据的约定。</td></tr><tr><td>齐次坐标</td><td>homogeneous coordinates</td><td>给 3D 坐标补第 4 个数，让平移/旋转/缩放统一成矩阵乘法。</td></tr><tr><td>矩阵乘法</td><td>matrix multiplication</td><td>两台变换机器串联成一台的算法：新矩阵每格 = 左矩阵一行与右矩阵一列的点积；乘积从右往左作用。</td></tr><tr><td>变换顺序不可交换</td><td>non-commutativity of transforms</td><td>交换两台变换机器的先后，结果不同（T·R ≠ R·T）；写变换组合时顺序是设计决定，不是细节。</td></tr><tr><td>模型矩阵</td><td>model matrix</td><td>把物体从自家局部位置摆到世界里的矩阵。</td></tr><tr><td>投影</td><td>projection</td><td>把眼前的三维场景压进 [-1,1] 标准操场的那一步变换；与第 4 章的向量投影同名不同义。</td></tr><tr><td>透视投影</td><td>perspective projection</td><td>学人眼的投影：近大远小，透视除法把远处的落点向中心收。</td></tr><tr><td>正交投影</td><td>orthographic projection</td><td>平行投影：光线全平行，远近不影响大小，平行线保持平行。</td></tr><tr><td>宽高比</td><td>aspect ratio</td><td>画布宽除以高；透视矩阵用它预压 x，画布非正方形时圆不变椭圆。</td></tr><tr><td>视图矩阵</td><td>view matrix</td><td>把世界搬进相机眼前（相机坐回原点朝 -Z）的矩阵。</td></tr><tr><td>投影矩阵</td><td>projection matrix</td><td>把相机前方的三维场景压进 [-1,1] 标准操场的矩阵。</td></tr><tr><td>视锥体</td><td>view frustum</td><td>相机可见的空间：从眼睛出发被屏幕四边削出的一顶帐篷。</td></tr><tr><td>透视除法</td><td>perspective divide</td><td>坐标除以自身深度 w，近大远小的数学来源。</td></tr><tr><td>相机</td><td>camera</td><td>虚构的取景机器：眼在哪、看哪、头正不正三问的答案，全部由视图矩阵代办——WebGL 的 API 里没有相机这个岗位。</td></tr><tr><td>上向量</td><td>up vector</td><td>lookAt 三要素之一，管「头正不正」：大致的头顶方向，内部扶正成严格垂直；与视线平行时 lookAt 退化。</td></tr><tr><td>正交基</td><td>orthogonal basis</td><td>两两垂直、各自单位长的向量组；lookAt 现造 f/s/u 三根正交基装出视图矩阵的旋转部分。</td></tr><tr><td>MVP</td><td>model-view-projection</td><td>模型、视图、投影三台矩阵的串联 P·V·M：坐标先过 M（摆进世界）、再过 V（搬到相机眼前）、最后过 P（压进操场）。</td></tr><tr><td>深度缓冲</td><td>depth buffer</td><td>每像素记录当前最近深度的清单，遮挡判断的账本。</td></tr><tr><td>深度测试</td><td>depth test</td><td>新片元与账本比远近，更近才许上屏的规则。</td></tr><tr><td>画家算法</td><td>painter&#39;s algorithm</td><td>按远近从后往前画、近者覆盖远者的整体排序画法；互相穿插或自翻折的面会失效，逐像素的深度测试才是完备解。</td></tr><tr><td>索引绘制</td><td>indexed drawing</td><td>顶点存一份、面用编号清单引用的复用画法（drawElements）。</td></tr><tr><td>缠绕方向</td><td>winding order</td><td>顶点连成面的时针方向，用于判定面的正反。</td></tr><tr><td>背面剔除</td><td>backface culling</td><td>背对相机的面直接不画的省事规则。</td></tr><tr><td>交错缓冲</td><td>interleaved buffer</td><td>把 position/normal/uv 等逐顶点属性按顶点挨个排进同一张表；取数按固定步长跳格，各属性按偏移对号。</td></tr><tr><td>纹理</td><td>texture</td><td>贴在表面的图片数据，由 GPU 按坐标取样。</td></tr><tr><td>UV 坐标</td><td>texture coordinates</td><td>纹理上的归一化寻址坐标，左下角 (0,0) 到右上角 (1,1)。</td></tr><tr><td>纹素</td><td>texel</td><td>纹理里的一个像素。</td></tr><tr><td>采样</td><td>sampling</td><td>按 UV 从纹理取颜色的动作。</td></tr><tr><td>过滤</td><td>filtering</td><td>UV 落在纹素之间时的取色策略：NEAREST 取最近块，LINEAR 调匀。</td></tr><tr><td>包裹方式</td><td>texture wrapping</td><td>UV 越出 [0,1] 时的处理规则：REPEAT 取小数部分平铺贴图；CLAMP_TO_EDGE 摁在边缘，最后一排纹素被拉伸。</td></tr><tr><td>程序化纹理</td><td>procedural texture</td><td>用代码算出纹素数据的纹理——不读图片文件，图案即函数；零外部资源、可确定性重生成。</td></tr><tr><td>法线</td><td>normal</td><td>垂直于表面的单位向量，表面接光的姿势。</td></tr><tr><td>法线矩阵</td><td>normal matrix</td><td>模型矩阵的逆转置，把法线的垂直关系变换正确的专用矩阵。</td></tr><tr><td>环境光</td><td>ambient light</td><td>无方向兜底光，让背光面不至于纯黑。</td></tr><tr><td>漫反射</td><td>diffuse reflection</td><td>粗糙面把光向四面八方弹开的分量，正对光最亮。</td></tr><tr><td>高光</td><td>specular highlight</td><td>光滑面朝相机弹出的反光斑，光洁度越高越集中。</td></tr><tr><td>Phong 光照模型</td><td>Phong reflection model</td><td>把表面亮度拆成环境光 + 漫反射 + 高光三个分量的经典光照模型（Bui Tuong Phong，1975）；不是物理精确，但便宜、直觉、效果像样。</td></tr><tr><td>场景图</td><td>scene graph</td><td>父子上级的层级结构，子物体坐标跟随父链组合。</td></tr><tr><td>局部矩阵</td><td>local matrix</td><td>节点相对父级的变换。</td></tr><tr><td>世界矩阵</td><td>world matrix</td><td>从根链乘到本节点的总变换，物体在世界里的最终姿势。</td></tr><tr><td>层级动画</td><td>hierarchical animation</td><td>每帧只改各节点的局部矩阵（自转角、公转角），世界坐标由 updateWorld 链乘自动结算的动画写法——父级一动，整棵子树跟着动。</td></tr><tr><td>遍历绘制</td><td>traversal rendering</td><td>深度优先走一遍场景树、每个节点用它当时的世界矩阵当模型矩阵画一次的绘制方式。</td></tr><tr><td>轨道相机</td><td>orbit camera</td><td>相机绕目标点沿球面转圈的查看方式。</td></tr><tr><td>偏航角</td><td>yaw</td><td>左右转头的角度。</td></tr><tr><td>俯仰角</td><td>pitch</td><td>上下点头的角度。</td></tr><tr><td>球坐标</td><td>spherical coordinates</td><td>用「转到哪边、抬多高、离多远」——两个角加一个半径——定位一个点的坐标法；轨道相机的眼位账本。</td></tr><tr><td>相机基向量</td><td>camera basis</td><td>相机自己的前、右、上三根两两垂直的单位向量；朝向与移动都沿它们走，不沿世界轴。</td></tr><tr><td>雾</td><td>fog</td><td>按距离把远处景物混入雾色的纵深手法；factor = smoothstep(near, far, 距离)，片元色 = mix(物体色, 雾色, factor)。</td></tr><tr><td>材质</td><td>material</td><td>形状的皮肤参数包：基础色、三件套强度、光洁度、自发光；纯数据可共享，挂在节点的 data 挂件上。</td></tr><tr><td>自发光</td><td>emissive</td><td>材质里不等光照、自己亮的分量 [0,1]；太阳靠它标记光源，演示里自发光免雾（光源穿雾可见）。</td></tr><tr><td>程序化布局</td><td>procedural layout</td><td>用一段代码加一个种子数决定什么东西摆在哪——代码是布局规则，种子是这一次的掷骰结果；同种子同世界。</td></tr><tr><td>渲染清单</td><td>render list</td><td>遍历场景树收集出的「这一帧画什么」数组：每行一个 (形状, 世界矩阵, 材质) 三元组，绘制只剩一个通用循环。</td></tr><tr><td>种子随机数</td><td>seeded random number generator</td><td>由种子数决定的固定随机序列：同种子从头再生成，每个数与顺序逐位相同——「按种子重建地图」的机关。</td></tr><tr><td>GPU</td><td>graphics processing unit</td><td>几千个简单计算单元并联的芯片，靠同时干活取胜，专吃图形这类重复计算。</td></tr><tr><td>渲染管线</td><td>rendering pipeline</td><td>从坐标到像素的三段流水线：顶点定位置、光栅化圈格子、片元上颜色。</td></tr><tr><td>帧率</td><td>frame rate</td><td>每秒画出的完整画面数；60fps 意味着每帧只有约 16.7ms 预算。</td></tr><tr><td>掉帧</td><td>frame drop</td><td>一帧没赶上屏幕刷新节拍，那一拍只能重复旧画面，看起来就是卡顿。</td></tr><tr><td>视锥剔除</td><td>frustum culling</td><td>收单前在 CPU 上用包围球判断物体整件在不在视锥（帐篷）内，帐外的不进渲染清单——省的是整次绘制调用；判定宁可错画、不可错删。</td></tr><tr><td>实例化渲染</td><td>instanced rendering</td><td>一份几何加一张实例表、一次绘制调用画 N 件同样物体的画法；每实例的顶点属性每件前进一步，省的是 CPU 侧逐件发单的固定开销——不是少画，是少跑腿。</td></tr><tr><td>WebGL2</td><td>WebGL 2.0</td><td>WebGL 1 的下一代规范，基于 OpenGL ES 3.0 的严格超集（旧代码照跑）：实例化绘制转正、多渲染目标、非 2 幂纹理放开、GLSL ES 3.00、变换反馈、深度纹理原生。</td></tr><tr><td>WebGPU</td><td>WebGPU API</td><td>WebGL 的继任者，架构对齐 Vulkan/Metal/Direct3D 12 一代本地图形 API：计算着色器一等公民、显式管线对象（创建时验证）、CPU 侧逐物体开销更低；着色语言为 WGSL。概念换名不换账。</td></tr></tbody></table>',3)])])}const u=d(o,[["render",i]]);export{g as __pageData,u as default};
